#!/usr/bin/env bash
set -uo pipefail
REPO_DIR="${CARE_ASD_REPO_DIR:-$HOME/Dung_TDTU/CARE_ASD}"; DATA_ROOT="${CARE_ASD_DATA_ROOT:-$HOME/Dung_TDTU/data/CARE_ASD}"; cd "$REPO_DIR"; RUN_FILE="outputs/fp_naa/latest_reference_safety_run_id.txt"
if [ ! -f "$RUN_FILE" ]; then printf 'No FP-NAA reference-safety run has been started.\n'; exit 0; fi
RUN_ID="$(cat "$RUN_FILE")"; JOB_DIR="outputs/fp_naa/$RUN_ID"; REPORT_DIR="reports/fp_naa/$RUN_ID/reference_safety"; SAFETY_CACHE="$DATA_ROOT/fp_naa/reference_safety_cache/dev/waveform_v1"; printf 'RUN_ID=%s\n\nSTATE:\n' "$RUN_ID"; [ -f "$JOB_DIR/state.env" ] && cat "$JOB_DIR/state.env" || printf 'state file not created yet\n'; printf '\nPROCESS:\n'; pgrep -af '[r]un_fp_naa_reference_safety.sh|care-asd fp-naa (cache-reference-safety|reference-safety-dev)' || printf 'no matching process\n'; printf '\nCACHE PROGRESS:\n'; [ -f "$SAFETY_CACHE/progress.env" ] && cat "$SAFETY_CACHE/progress.env" || printf 'safety cache progress not created yet\n'; printf '\nEVALUATION PROGRESS:\n'; [ -f "$REPORT_DIR/progress.env" ] && cat "$REPORT_DIR/progress.env" || printf 'safety evaluation progress not created yet\n'; printf '\nRESOURCE SNAPSHOT:\n'; ps -eo pid,etime,stat,pcpu,pmem,args | grep -E '[c]are-asd fp-naa (cache-reference-safety|reference-safety-dev)|[r]un_fp_naa_reference_safety' || true; printf '\nGPU:\n'; nvidia-smi --query-compute-apps=pid,process_name,used_memory --format=csv,noheader 2>/dev/null || true; printf '\nLOG TAIL:\n'; tail -n 30 "$JOB_DIR/fp_naa_reference_safety.log" 2>/dev/null || true; if [ -f "$REPORT_DIR/reference_safety_summary.csv" ]; then printf '\nSUMMARY:\n'; column -s, -t < "$REPORT_DIR/reference_safety_summary.csv"; fi; if [ -f "$REPORT_DIR/gate.json" ]; then printf '\nGATE:\n'; cat "$REPORT_DIR/gate.json"; fi
